package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.mining.*;import io.xeros.content.skills.mining.CoreRockMining.Rock;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.collisionmap.*;import java.util.*;import java.util.function.IntUnaryOperator;
public final class MiningToolsCheck {
 static void ok(boolean b,String why){if(!b)throw new AssertionError(why);}static Player actor(){Player p=AttackDefencePlayableCheck.actor();p.setLoginName("minetoolqa");p.setDisplayName("Minetoolqa");return p;}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void tick(int n){SkillsAuditCheck.tick(n);}
 static void xp(Player p,int skill,int before,double... values){Player q=actor();int old=q.playerXP[skill];for(double v:values)q.getPA().addSkillXPMultiplied(v,skill,true);ok(p.playerXP[skill]-before==q.playerXP[skill]-old,"XP skill="+skill+" delta="+(p.playerXP[skill]-before));}
 static void ring(){
  for(int id:new int[]{25539,25543}){
   Player p=actor();give(p,id,1);give(p,25527,10020);ok(p.getMiningTools().charge(id),"Charge ring/signet");ok(count(p,id)==0&&count(p,id+2)==1&&count(p,25527)==20&&p.getMiningTools().charges(id)==10000,"10000 cap/material remainder");ok(!p.getMiningTools().charge(id+2)&&count(p,25527)==20,"Overcharge consumed dust");
   while(p.getItems().freeSlots()>0)give(p,229,1);ok(p.getMiningTools().uncharge(id+2)&&count(p,id)==1&&count(p,25527)==10020&&p.getMiningTools().charges(id)==0,"Full inventory uncharge merges existing dust");
   p.getItems().deleteItem2(25527,10020);p.getItems().deleteItem2(229,1);give(p,25527,5);ok(p.getMiningTools().charge(id)&&p.getMiningTools().charges(id)==5,"Recharge partial");while(p.getItems().freeSlots()>0)give(p,229,1);ok(!p.getMiningTools().uncharge(id+2)&&count(p,id+2)==1&&p.getMiningTools().charges(id)==5&&count(p,25527)==0,"Uncharge without free dust slot lost items/charges");
  }
  Player p=actor();give(p,25539,1);give(p,25527,2);p.getMiningTools().itemOnItem(25527,25539);ok(count(p,25541)==1&&p.getMiningTools().charges(25541)==2,"Stardust use reverse order");p.playerEquipment[Player.playerRing]=25541;p.playerEquipmentN[Player.playerRing]=1;p.getItems().deleteItem2(25541,1);
  ok(!p.getMiningTools().ringBonus(Rock.IRON,b->9)&&p.getMiningTools().charges(25541)==1,"Charge consumed even without bonus");ok(p.getMiningTools().ringBonus(Rock.IRON,b->0)&&p.getMiningTools().charges(25541)==0&&p.playerEquipment[Player.playerRing]==25539,"Last charge bonus and worn model depletion");
  p.getMiningTools().decode("5000,5,5");p.playerEquipment[Player.playerRing]=25541;ok(!p.getMiningTools().ringBonus(Rock.RUNITE,b->0)&&!p.getMiningTools().ringBonus(Rock.ESSENCE,b->0)&&p.getMiningTools().charges(25541)==5,"Excluded rocks consumed charge");
  System.out.println("MINING_TOOLS_BOTH_CELESTIAL_CONTAINERS_CAP10000_DUST_REMAINDERS_UNCHARGE_ATOMIC_SPACE_LAST_CHARGE_EQUIPPED_MODEL_AND_ORE_EXCLUSIONS_OK");
 }
 static void creation(){
  for(int missing:new int[]{11920,13233}){Player p=actor();give(p,missing,1);int mine=p.playerXP[14],smith=p.playerXP[13];p.getMiningTools().create();tick(3);ok(count(p,13243)==0&&p.playerXP[14]==mine&&p.playerXP[13]==smith,"Missing reagent creation");SkillsAuditCheck.clear(p);}
  for(int skill:new int[]{13,14}){Player p=actor();give(p,11920,1);give(p,13233,1);p.playerXP[skill]=p.getPA().getXPForLevel(skill==13?84:60);p.playerLevel[skill]=99;ok(!p.getMiningTools().create()&&count(p,11920)==1&&count(p,13233)==1,"Unboostable creation requirements");}
  Player p=actor();give(p,11920,1);give(p,13233,1);int mine=p.playerXP[14],smith=p.playerXP[13];ok(p.getMiningTools().create(),"Creation starts");tick(2);ok(count(p,13243)==0&&p.playerXP[14]==mine&&p.playerXP[13]==smith,"Early creation");tick(1);ok(count(p,13243)==1&&count(p,11920)==0&&count(p,13233)==0&&p.getMiningTools().infernal()==5000,"Creation materials/result");xp(p,14,mine,200);xp(p,13,smith,350);SkillsAuditCheck.clear(p);
  give(p,11920,1);give(p,13233,1);ok(!p.getMiningTools().create()&&count(p,11920)==1&&count(p,13233)==1,"Duplicate charged tool ownership");p.getMiningTools().decode("1,0,0");p.getMiningTools().itemOnItem(13243,13233);tick(4);ok(p.getMiningTools().infernal()==1&&count(p,13233)==1,"Post2026 partial recharge leaked into2022");SkillsAuditCheck.clear(p);
  Player removed=actor();give(removed,11920,1);give(removed,13233,1);removed.getMiningTools().create();removed.getItems().deleteItem2(13233,1);tick(3);ok(count(removed,13243)==0&&count(removed,11920)==1,"Creation after reagent removal");SkillsAuditCheck.clear(removed);
  for(int material:new int[]{11920,13233}){Player q=actor();give(q,13244,1);give(q,material,1);q.getMiningTools().decode("0,0,0");ok(q.getMiningTools().itemOnItem(material,13244),"Recharge dispatch");tick(3);ok(count(q,13244)==0&&count(q,material)==0&&count(q,13243)==1&&q.getMiningTools().infernal()==5000,"Recharge materials/counter");SkillsAuditCheck.clear(q);}
  System.out.println("MINING_TOOLS_INFERNAL_BASE61_85_GATES_THREE_TICK_ATOMIC_CREATE_XP200_350_MISSING_REMOVED_REAGENTS_OLD_RECHARGE_RULE_AND_TWO_REAGENTS_OK");
 }
 static void combustion(){
  Rock[] rocks={Rock.COPPER,Rock.TIN,Rock.IRON,Rock.SILVER,Rock.COAL,Rock.GOLD,Rock.MITHRIL,Rock.ADAMANT,Rock.RUNITE,Rock.BLURITE};double[] awards={3.6,3.6,5.5,5.5,6,9,12,18.75,25,4};
  for(int i=0;i<rocks.length;i++){Player p=actor();give(p,13243,1);int before=p.playerXP[13];ok(!p.getMiningTools().combust(rocks[i],b->2)&&p.getMiningTools().infernal()==5000,"Two-thirds no combustion");ok(p.getMiningTools().combust(rocks[i],b->0)&&p.getMiningTools().infernal()==4999,"One-third combustion");xp(p,13,before,awards[i]);}
  Player p=actor();give(p,13243,1);p.getMiningTools().decode("1,0,0");ok(p.getMiningTools().combust(Rock.RUNITE,b->0)&&count(p,13243)==0&&count(p,13244)==1&&p.getMiningTools().infernal()==0,"Inventory final charge model");ok(!p.getMiningTools().combust(Rock.RUNITE,b->0),"Depleted tool still burns");
  Player worn=actor();worn.playerEquipment[Player.playerWeapon]=13243;worn.playerEquipmentN[Player.playerWeapon]=1;worn.getMiningTools().decode("1,0,0");ok(worn.getMiningTools().combust(Rock.COAL,b->0)&&worn.playerEquipment[Player.playerWeapon]==13244,"Worn final charge model");
  Player excluded=actor();give(excluded,13243,1);for(Rock r:new Rock[]{Rock.CLAY,Rock.SOFT_CLAY,Rock.ESSENCE})ok(!excluded.getMiningTools().combust(r,b->0)&&excluded.getMiningTools().infernal()==5000,"Excluded combustion "+r);
  excluded.playerLevel[13]=84;ok(Pickaxe.getBestPickaxe(excluded)==null,"Infernal Smithing use gate");give(excluded,1275,1);ok(Pickaxe.getBestPickaxe(excluded)==Pickaxe.RUNE,"Fallback tool while infernal blocked");
  Player black=actor();black.playerLevel[14]=11;give(black,12297,1);ok(Pickaxe.getBestPickaxe(black)==Pickaxe.BLACK,"Black pickaxe level11");
  System.out.println("MINING_TOOLS_TEN_COMBUSTION_XP_VALUES_ONE_THIRD_CHARGE_USE_WORN_INVENTORY_DEPLETION_NO_FREE_BARS_EXCLUSIONS_TOOL_FALLBACK_AND_BLACK11_OK");
 }
 static void actual(List<WorldObject> nodes){
  WorldObject o=CoreRockMiningCheck.node(nodes,Rock.IRON);Player p=CoreRockMiningCheck.actor(o);p.getItems().deleteItem2(1275,1);give(p,13243,1);p.playerEquipment[Player.playerRing]=25541;p.playerEquipmentN[Player.playerRing]=1;p.getMiningTools().decode("5000,1,0");int mine=p.playerXP[14],smith=p.playerXP[13];
  IntUnaryOperator both=b->b==256||b==3||b==10?0:b-1;ok(CoreRockMining.start(p,o.id,o.x,o.y,both),"Infernal/ring real rock start");tick(3);SkillsAuditCheck.clear(p);ok(count(p,440)==0&&count(p,2351)==0&&p.getMiningTools().infernal()==4998&&p.playerEquipment[Player.playerRing]==25539,"Both ores combust, no bar, exact two charges and ring depletion");xp(p,14,mine,35,35);xp(p,13,smith,5.5,5.5);CoreRockMiningCheck.restore(o);
  Player full=CoreRockMiningCheck.actor(o);full.playerEquipment[Player.playerRing]=25541;full.playerEquipmentN[Player.playerRing]=1;full.getMiningTools().decode("5000,1,0");while(full.getItems().freeSlots()>1)give(full,229,1);mine=full.playerXP[14];CoreRockMining.start(full,o.id,o.x,o.y,b->b==256||b==10?0:b-1);tick(3);SkillsAuditCheck.clear(full);ok(count(full,440)==1&&full.getMiningTools().charges(25541)==0,"Ring full inventory must lose second ore but consume charge");xp(full,14,mine,35);CoreRockMiningCheck.restore(o);
  Player pre=CoreRockMiningCheck.actor(o);pre.playerEquipment[Player.playerRing]=25541;pre.getMiningTools().decode("5000,3,0");CoreRockMining.start(pre,o.id,o.x,o.y,b->b==32768?70:b-1);tick(3);SkillsAuditCheck.clear(pre);ok(count(pre,1623)==1&&pre.getMiningTools().charges(25541)==3,"Gem pre-roll must not debit ring");
  System.out.println("MINING_TOOLS_REAL_ORE_RING_AND_INFERNAL_STACK_BOTH_RESOURCES_CONSUMED_SMITH_MINING_XP_NO_BAR_FULL_INVENTORY_SECOND_ORE_LOSS_AND_GEM_NO_CHARGE_OK");
 }
 static void save(){Player p=actor();give(p,13243,1);p.getMiningTools().decode("1234,5678,9012");p.setIndex(1);p.saveCharacter=true;p.isActive=true;PlayerHandler.players[1]=p;ok(PlayerSave.saveGameInstant(p),"Charge save");Player q=actor();ok(PlayerSave.loadGame(q,"minetoolqa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.getMiningTools().encode().equals("1234,5678,9012"),"Exact charge reload");for(String bad:new String[]{"", "5001,0,0","1,10001,0","1,0,10001","-1,0,0","1,2","1,2,3,4","NaN,2,3"})ok(!q.getMiningTools().decode(bad)&&q.getMiningTools().encode().equals("1234,5678,9012"),"Atomic malformed charge state");PlayerHandler.players[1]=null;System.out.println("MINING_TOOLS_ACTUAL_SAVE_RELOAD_ALL_THREE_CHARGE_COUNTERS_AND_EIGHT_MALFORMED_ATOMIC_REJECTIONS_OK");}
 static void wield(){
  int[][] requirements={{1265,1},{1267,1},{1269,5},{12297,10},{1273,20},{1271,30},{1275,40},{11920,60},{12797,60},{23677,60},{13243,60},{13244,60},{20014,65}};
  for(int[] entry:requirements){int id=entry[0],level=entry[1];Player p=actor();give(p,id,1);p.playerLevel[14]=1;p.playerXP[14]=0;p.playerXP[0]=p.getPA().getXPForLevel(level);p.playerLevel[0]=level;ok(p.getItems().equipItem(id,0)&&p.playerEquipment[Player.playerWeapon]==id,"Native wield should need Attack, not Mining "+id);if(level>1){Player low=actor();give(low,id,1);low.playerXP[0]=low.getPA().getXPForLevel(level-1);low.playerLevel[0]=level-1;ok(!low.getItems().equipItem(id,0)&&count(low,id)==1,"Below Attack requirement wielded pickaxe "+id);}}
  System.out.println("MINING_TOOLS_THIRTEEN_NATIVE_PICKAXE_WIELD_GATES_ATTACK_LEVELS_SEPARATE_FROM_MINING_AND_BELOW_LEVEL_REJECTION_OK");
 }
 public static void main(String[] args)throws Exception{try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Configuration.BONUS_SKILL_TIMER=Long.MAX_VALUE;ring();creation();combustion();actual(CoreRockMiningCheck.nodes());wield();save();System.out.println("MINING_TOOLS_ALL_CHECKS_PASSED");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
